import { LIGHTHOUSE_SAMPLE_COUNT, lighthouseBudgets } from "./lighthouse-policy.mjs";

const safeErrorMessages = {
  PREVIEW_UNAVAILABLE: "Production preview did not become available.",
  LIGHTHOUSE_SAMPLE_FAILED: "A Lighthouse sample could not be collected.",
  LIGHTHOUSE_POLICY_FAILED: "Lighthouse policy validation failed.",
  CHROME_CLEANUP_FAILED: "Lighthouse Chrome cleanup did not complete.",
  PREVIEW_CLEANUP_FAILED: "Production preview cleanup did not complete.",
  EVIDENCE_PERSIST_FAILED: "Lighthouse evidence could not be persisted.",
};

export function createAuditError(code, message, cause) {
  const error = new Error(message, cause === undefined ? undefined : { cause });
  error.code = code;
  return error;
}

export function sanitizeAuditError(error) {
  const code = findSafeErrorCode(error) ?? "AUDIT_FAILED";
  return {
    code,
    message: safeErrorMessages[code] ?? "Lighthouse audit did not complete.",
  };
}

export function createLighthouseEvidence({
  status,
  source,
  samples,
  aggregation,
  failedAccessibilityAudits,
  failures,
  error,
}) {
  return {
    schemaVersion: 2,
    recordedAt: new Date().toISOString(),
    status,
    source,
    profile: {
      target: "Lighthouse default mobile emulation against the production /login bundle",
      samples: LIGHTHOUSE_SAMPLE_COUNT,
      browser: "A fresh headless Chrome process per sample against one shared production preview server",
    },
    completedSamples: samples.length,
    samples,
    aggregation:
      aggregation == null
        ? null
        : {
            performanceAndTiming: "median",
            accessibilityAndBestPractices: "minimum",
            observed: aggregation,
          },
    failedAccessibilityAudits,
    budgets: lighthouseBudgets,
    failures,
    error: error == null ? null : sanitizeAuditError(error),
  };
}

export async function stopPreviewProcess(preview, options = {}) {
  const graceTimeoutMs = options.graceTimeoutMs ?? 5_000;
  const forceTimeoutMs = options.forceTimeoutMs ?? 5_000;
  const waitForExit = options.waitForExit ?? waitForProcessExit;

  if (hasExited(preview)) return;
  sendSignal(preview, "SIGTERM");
  if (await waitForExit(preview, graceTimeoutMs)) return;

  sendSignal(preview, "SIGKILL");
  if (await waitForExit(preview, forceTimeoutMs)) return;

  throw createAuditError("PREVIEW_CLEANUP_FAILED", "Preview process did not terminate after SIGKILL.");
}

export function combineAuditFailures(primaryFailure, finalizationFailures) {
  const materialFinalizationFailures = finalizationFailures.filter(Boolean);
  if (primaryFailure == null) {
    if (materialFinalizationFailures.length === 0) return null;
    if (materialFinalizationFailures.length === 1) return materialFinalizationFailures[0];
    return new AggregateError(materialFinalizationFailures, "Lighthouse finalization failed.");
  }
  if (materialFinalizationFailures.length === 0) return primaryFailure;
  return new AggregateError(
    [primaryFailure, ...materialFinalizationFailures],
    "Lighthouse audit failed and finalization also failed.",
  );
}

export async function finalizeLighthouseSample(primaryFailure, closeChrome) {
  let cleanupFailure = null;
  try {
    await closeChrome();
  } catch (error) {
    cleanupFailure = createAuditError("CHROME_CLEANUP_FAILED", "Chrome cleanup failed.", error);
  }

  const finalFailure = combineAuditFailures(primaryFailure, [cleanupFailure]);
  if (finalFailure != null) throw finalFailure;
}

function hasExited(process) {
  return process.exitCode != null || process.signalCode != null;
}

function findSafeErrorCode(error) {
  if (typeof error?.code === "string" && safeErrorMessages[error.code]) return error.code;
  if (error instanceof AggregateError) {
    return error.errors.map(findSafeErrorCode).find(Boolean);
  }
  return null;
}

function sendSignal(process, signal) {
  try {
    if (process.kill(signal) === false && !hasExited(process)) {
      throw new Error("process was not running");
    }
  } catch (error) {
    throw createAuditError("PREVIEW_CLEANUP_FAILED", `Preview process rejected ${signal}.`, error);
  }
}

function waitForProcessExit(process, timeoutMs) {
  if (hasExited(process)) return Promise.resolve(true);

  return new Promise(resolve => {
    let settled = false;
    let timeout = null;
    const finish = result => {
      if (settled) return;
      settled = true;
      if (timeout != null) clearTimeout(timeout);
      process.off("exit", onExit);
      process.off("close", onExit);
      resolve(result);
    };
    const onExit = () => finish(true);
    process.once("exit", onExit);
    process.once("close", onExit);
    if (hasExited(process)) {
      finish(true);
      return;
    }
    timeout = setTimeout(() => finish(false), timeoutMs);
  });
}

import assert from "node:assert/strict";
import { EventEmitter } from "node:events";
import test from "node:test";

import {
  combineAuditFailures,
  createAuditError,
  createLighthouseEvidence,
  finalizeLighthouseSample,
  sanitizeAuditError,
  stopPreviewProcess,
} from "./lighthouse-audit-support.mjs";

test("failed Lighthouse evidence retains completed samples and sanitizes the source error", () => {
  const unsafeError = createAuditError(
    "LIGHTHOUSE_SAMPLE_FAILED",
    "Chrome failed at /tmp/private-profile?token=secret-value",
  );
  const evidence = createLighthouseEvidence({
    status: "failed",
    source: { commit: "commit", runId: "run" },
    samples: [{ number: 1, observed: { performance: 0.8 } }],
    aggregation: null,
    failedAccessibilityAudits: [],
    failures: [],
    error: unsafeError,
  });

  assert.equal(evidence.schemaVersion, 2);
  assert.equal(evidence.status, "failed");
  assert.equal(evidence.completedSamples, 1);
  assert.deepEqual(evidence.error, {
    code: "LIGHTHOUSE_SAMPLE_FAILED",
    message: "A Lighthouse sample could not be collected.",
  });
  assert.doesNotMatch(JSON.stringify(evidence), /tmp\/private-profile|secret-value/);
});

test("unknown audit errors are replaced with a generic safe evidence error", () => {
  assert.deepEqual(sanitizeAuditError(new Error("password=should-not-appear")), {
    code: "AUDIT_FAILED",
    message: "Lighthouse audit did not complete.",
  });
});

test("preview cleanup sends SIGKILL only after SIGTERM fails to stop the process", async () => {
  const signals = [];
  const process = {
    exitCode: null,
    signalCode: null,
    kill(signal) {
      signals.push(signal);
      return true;
    },
  };
  const waits = [false, true];

  await stopPreviewProcess(process, { waitForExit: async () => waits.shift() });

  assert.deepEqual(signals, ["SIGTERM", "SIGKILL"]);
});

test("preview cleanup does not signal a process that has already exited", async () => {
  let signals = 0;
  const process = {
    exitCode: 0,
    signalCode: null,
    kill() {
      signals += 1;
      return true;
    },
  };

  await stopPreviewProcess(process);

  assert.equal(signals, 0);
});

test("preview cleanup resolves an exit that races with listener registration", async () => {
  class ListenerRaceProcess extends EventEmitter {
    exitCode = null;
    signalCode = null;
    registeredExitListener = false;

    kill() {
      return true;
    }

    once(event, listener) {
      const result = super.once(event, listener);
      if (event === "exit" && !this.registeredExitListener) {
        this.registeredExitListener = true;
        this.exitCode = 0;
      }
      return result;
    }
  }

  await stopPreviewProcess(new ListenerRaceProcess(), {
    graceTimeoutMs: 1,
    forceTimeoutMs: 1,
  });
});

test("preview cleanup accepts kill(false) when the process has exited", async () => {
  const process = {
    exitCode: null,
    signalCode: null,
    kill() {
      this.exitCode = 0;
      return false;
    },
  };

  await stopPreviewProcess(process);
});

test("combined finalization failure retains the primary audit failure", () => {
  const primary = createAuditError("LIGHTHOUSE_POLICY_FAILED", "policy failed");
  const cleanup = createAuditError("PREVIEW_CLEANUP_FAILED", "cleanup failed");
  const failure = combineAuditFailures(primary, [cleanup]);

  assert.ok(failure instanceof AggregateError);
  assert.deepEqual(failure.errors, [primary, cleanup]);
  assert.deepEqual(sanitizeAuditError(failure), {
    code: "LIGHTHOUSE_POLICY_FAILED",
    message: "Lighthouse policy validation failed.",
  });
});

test("Chrome cleanup failure does not replace the primary Lighthouse sample failure", async () => {
  const primary = createAuditError("LIGHTHOUSE_SAMPLE_FAILED", "sample failed");

  await assert.rejects(
    finalizeLighthouseSample(primary, async () => {
      throw new Error("chrome profile /tmp/private-profile failed");
    }),
    error => {
      assert.ok(error instanceof AggregateError);
      assert.deepEqual(error.errors[0], primary);
      assert.deepEqual(sanitizeAuditError(error), {
        code: "LIGHTHOUSE_SAMPLE_FAILED",
        message: "A Lighthouse sample could not be collected.",
      });
      return true;
    },
  );
});

