import { spawn } from "node:child_process";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";
import { launch as launchChrome } from "chrome-launcher";
import lighthouse from "lighthouse";
import { LIGHTHOUSE_SAMPLE_COUNT, evaluateLighthouseSamples } from "./lighthouse-policy.mjs";
import {
  combineAuditFailures,
  createAuditError,
  createLighthouseEvidence,
  finalizeLighthouseSample,
  stopPreviewProcess,
} from "./lighthouse-audit-support.mjs";

const frontendRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const evidenceDirectory = path.resolve(frontendRoot, ".performance-evidence");
const preview = spawn(
  process.execPath,
  ["node_modules/vite/bin/vite.js", "preview", "--host", "127.0.0.1", "--strictPort"],
  {
    cwd: frontendRoot,
    env: process.env,
    stdio: ["ignore", "pipe", "pipe"],
  },
);

const audit = {
  aggregation: null,
  failures: [],
  samples: [],
  status: "failed",
};
let primaryFailure = null;

try {
  await waitForUrl("http://127.0.0.1:4173/login", 30_000);
  for (let sampleNumber = 1; sampleNumber <= LIGHTHOUSE_SAMPLE_COUNT; sampleNumber += 1) {
    const sample = await collectSample(sampleNumber);
    audit.samples.push(sample);
  }
  const result = evaluateLighthouseSamples(audit.samples.map(sample => sample.observed));
  audit.aggregation = result.aggregate;
  audit.failures = result.failures;
  if (audit.failures.length > 0) {
    throw createAuditError("LIGHTHOUSE_POLICY_FAILED", "Lighthouse budget policy failed.");
  }
  audit.status = "passed";
} catch (error) {
  primaryFailure = error;
}

const cleanupFailures = [];
try {
  await stopPreviewProcess(preview);
} catch (error) {
  cleanupFailures.push(error);
}

let finalFailure = combineAuditFailures(primaryFailure, cleanupFailures);
if (finalFailure != null) audit.status = "failed";

try {
  await persistEvidence(audit, finalFailure);
} catch (error) {
  const evidenceFailure = createAuditError("EVIDENCE_PERSIST_FAILED", "Lighthouse evidence persistence failed.", error);
  finalFailure = combineAuditFailures(finalFailure, [evidenceFailure]);
}

if (finalFailure != null) throw finalFailure;

console.log(`Lighthouse budgets passed: ${JSON.stringify(audit.aggregation)}.`);

async function persistEvidence(auditResult, error) {
  const failedAccessibilityAudits = auditResult.samples.flatMap(sample =>
    sample.failedAccessibilityAudits.map(audit => ({ ...audit, sample: sample.number })),
  );
  const evidence = createLighthouseEvidence({
    status: auditResult.status,
    source: { commit: process.env.GITHUB_SHA, runId: process.env.GITHUB_RUN_ID },
    samples: auditResult.samples,
    aggregation: auditResult.aggregation,
    failedAccessibilityAudits,
    failures: auditResult.failures,
    error,
  });

  await mkdir(evidenceDirectory, { recursive: true });
  await writeFile(path.join(evidenceDirectory, "lighthouse.json"), `${JSON.stringify(evidence, null, 2)}\n`);
}

async function collectSample(number) {
  let chrome;
  let sample = null;
  let primaryFailure = null;
  try {
    chrome = await launchChrome({
      chromePath: chromium.executablePath(),
      chromeFlags: ["--headless=new", "--no-sandbox", "--disable-dev-shm-usage"],
    });
    const result = await lighthouse("http://127.0.0.1:4173/login", {
      port: chrome.port,
      output: "json",
      logLevel: "error",
      onlyCategories: ["performance", "accessibility", "best-practices"],
    });
    if (!result) throw new Error("Lighthouse returned no result.");

    const report = result.lhr;
    const accessibilityAuditIds = new Set(report.categories.accessibility.auditRefs.map(reference => reference.id));
    sample = {
      number,
      lighthouseVersion: report.lighthouseVersion,
      userAgent: report.userAgent,
      observed: {
        performance: report.categories.performance.score,
        accessibility: report.categories.accessibility.score,
        bestPractices: report.categories["best-practices"].score,
        firstContentfulPaintMs: report.audits["first-contentful-paint"].numericValue,
        largestContentfulPaintMs: report.audits["largest-contentful-paint"].numericValue,
        totalBlockingTimeMs: report.audits["total-blocking-time"].numericValue,
        cumulativeLayoutShift: report.audits["cumulative-layout-shift"].numericValue,
      },
      failedAccessibilityAudits: Object.values(report.audits)
        .filter(audit => accessibilityAuditIds.has(audit.id) && audit.score != null && audit.score < 1)
        .map(audit => ({ id: audit.id, score: audit.score, title: audit.title })),
    };
  } catch (error) {
    primaryFailure = createAuditError(
      "LIGHTHOUSE_SAMPLE_FAILED",
      `Lighthouse sample ${number} could not be collected.`,
      error,
    );
  }

  await finalizeLighthouseSample(primaryFailure, async () => chrome?.kill());
  return sample;
}

async function waitForUrl(url, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (preview.exitCode != null || preview.signalCode != null) {
      throw createAuditError("PREVIEW_UNAVAILABLE", "Vite preview exited before becoming available.");
    }
    try {
      const response = await fetch(url);
      if (response.ok) return;
    } catch {
      // The server is still starting.
    }
    await new Promise(resolve => setTimeout(resolve, 200));
  }
  throw createAuditError("PREVIEW_UNAVAILABLE", "Timed out waiting for the Vite preview.");
}

export const LIGHTHOUSE_SAMPLE_COUNT = 3;

/**
 * These are production-bundle regression budgets, not field-performance SLOs.
 * Category scores use the configured aggregate while timing metrics also retain
 * their existing per-sample hard caps so one pathological run cannot be hidden
 * by the median.
 */
export const lighthouseBudgets = Object.freeze({
  performance: { aggregate: "median", minimum: 0.75 },
  accessibility: { aggregate: "minimum", minimum: 1 },
  bestPractices: { aggregate: "minimum", minimum: 0.9 },
  firstContentfulPaintMs: { aggregate: "median", maximum: 4_000, rawMaximum: 4_000 },
  largestContentfulPaintMs: { aggregate: "median", maximum: 5_000, rawMaximum: 5_000 },
  totalBlockingTimeMs: { aggregate: "median", maximum: 500, rawMaximum: 500 },
  cumulativeLayoutShift: { aggregate: "median", maximum: 0.1, rawMaximum: 0.1 },
});

export function aggregateLighthouseSamples(samples) {
  requireSamples(samples);

  return Object.fromEntries(
    Object.entries(lighthouseBudgets).map(([metric, budget]) => {
      const values = samples.map(sample => sample[metric]);
      return [metric, budget.aggregate === "minimum" ? Math.min(...values) : median(values)];
    }),
  );
}

export function evaluateLighthouseSamples(samples) {
  requireSamples(samples);
  const aggregate = aggregateLighthouseSamples(samples);
  const failures = [];

  for (const [metric, budget] of Object.entries(lighthouseBudgets)) {
    const aggregateValue = aggregate[metric];
    if ("minimum" in budget && aggregateValue < budget.minimum) {
      failures.push(`${metric} aggregate was ${aggregateValue}; minimum is ${budget.minimum}`);
    }
    if ("maximum" in budget && aggregateValue > budget.maximum) {
      failures.push(`${metric} aggregate was ${aggregateValue}; maximum is ${budget.maximum}`);
    }

    for (const [sampleIndex, sample] of samples.entries()) {
      const sampleValue = sample[metric];
      if (
        (metric === "accessibility" || metric === "bestPractices") &&
        "minimum" in budget &&
        sampleValue < budget.minimum
      ) {
        failures.push(`${metric} sample ${sampleIndex + 1} was ${sampleValue}; minimum is ${budget.minimum}`);
      }
      if ("rawMaximum" in budget && sampleValue > budget.rawMaximum) {
        failures.push(`${metric} sample ${sampleIndex + 1} was ${sampleValue}; hard maximum is ${budget.rawMaximum}`);
      }
    }
  }

  return { aggregate, failures };
}

function median(values) {
  const sorted = [...values].sort((left, right) => left - right);
  return sorted[Math.floor(sorted.length / 2)];
}

function requireSamples(samples) {
  if (!Array.isArray(samples) || samples.length !== LIGHTHOUSE_SAMPLE_COUNT) {
    throw new Error(`Lighthouse policy requires exactly ${LIGHTHOUSE_SAMPLE_COUNT} samples.`);
  }
  for (const [sampleIndex, sample] of samples.entries()) {
    for (const metric of Object.keys(lighthouseBudgets)) {
      if (!Number.isFinite(sample?.[metric])) {
        throw new Error(`Lighthouse sample ${sampleIndex + 1} has no finite ${metric} value.`);
      }
    }
  }
}

import assert from "node:assert/strict";
import test from "node:test";

import { aggregateLighthouseSamples, evaluateLighthouseSamples, lighthouseBudgets } from "./lighthouse-policy.mjs";

const atBudget = {
  performance: 0.75,
  accessibility: 1,
  bestPractices: 0.9,
  firstContentfulPaintMs: 4_000,
  largestContentfulPaintMs: 5_000,
  totalBlockingTimeMs: 500,
  cumulativeLayoutShift: 0.1,
};

test("Lighthouse policy accepts metrics exactly at every budget", () => {
  const result = evaluateLighthouseSamples([atBudget, atBudget, atBudget]);

  assert.deepEqual(result.aggregate, atBudget);
  assert.deepEqual(result.failures, []);
});

test("Lighthouse policy tolerates one composite-score outlier when the median passes", () => {
  const result = evaluateLighthouseSamples([
    { ...atBudget, performance: 0.5 },
    { ...atBudget, performance: 0.8 },
    { ...atBudget, performance: 0.8 },
  ]);

  assert.equal(result.aggregate.performance, 0.8);
  assert.deepEqual(result.failures, []);
});

test("Lighthouse policy fails when two regressed composite samples lower the median", () => {
  const result = evaluateLighthouseSamples([
    { ...atBudget, performance: 0.7 },
    { ...atBudget, performance: 0.7 },
    { ...atBudget, performance: 0.9 },
  ]);

  assert.equal(result.aggregate.performance, 0.7);
  assert.match(result.failures.join("\n"), /performance aggregate was 0.7/);
});

test("Lighthouse policy rejects an accessibility regression in any sample", () => {
  const result = evaluateLighthouseSamples([{ ...atBudget, accessibility: 0.99 }, atBudget, atBudget]);

  assert.match(result.failures.join("\n"), /accessibility sample 1 was 0.99/);
});

test("Lighthouse policy rejects a best-practices regression in any sample", () => {
  const result = evaluateLighthouseSamples([{ ...atBudget, bestPractices: 0.89 }, atBudget, atBudget]);

  assert.match(result.failures.join("\n"), /bestPractices sample 1 was 0.89/);
});

test("Lighthouse policy rejects a timing hard-cap violation in any sample", () => {
  const result = evaluateLighthouseSamples([{ ...atBudget, largestContentfulPaintMs: 5_001 }, atBudget, atBudget]);

  assert.match(result.failures.join("\n"), /largestContentfulPaintMs sample 1 was 5001; hard maximum is 5000/);
});

test("Lighthouse policy records the configured aggregation modes", () => {
  const aggregate = aggregateLighthouseSamples([
    { ...atBudget, performance: 0.75, accessibility: 1, bestPractices: 0.9 },
    { ...atBudget, performance: 0.8, accessibility: 0.95, bestPractices: 0.95 },
    { ...atBudget, performance: 0.9, accessibility: 1, bestPractices: 1 },
  ]);

  assert.equal(lighthouseBudgets.performance.aggregate, "median");
  assert.equal(aggregate.performance, 0.8);
  assert.equal(aggregate.accessibility, 0.95);
  assert.equal(aggregate.bestPractices, 0.9);
});

