              enabled: true,
              headless: true,
              provider: playwright({ contextOptions: { reducedMotion: "reduce" } }),
              instances: [{ browser: "chromium", name: "desktop-reduced", viewport: { height: 900, width: 1440 } }],
            },
          },
        },
      ],
    },
  }),
);

