import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import test from "node:test";

import { planCiChanges } from "./ci-change-plan.mjs";

const policy = JSON.parse(readFileSync(new URL("../contracts/ci-change-plan-policy.json", import.meta.url), "utf8"));
const intentionalFullVerification = [
  /^\.github\//u,
  /^\.gitleaks\.toml$/u,
  /^contracts\/(?:ci-change-plan-policy|github-actions-policy|verification-budget-policy|toolchain-policy)\.json$/u,
  /^scripts\/(?:ci-change-plan(?:-coverage)?(?:\.test)?|ci-required-contexts(?:\.test)?|workflow-security-policy|repository-security-policy|verification-pipeline-policy)\.mjs$/u,
  /^scripts\/verify-template\.sh$/u,
];

test("every tracked routine file has an explicit non-full routing classification", () => {
  const result = spawnSync("git", ["ls-files", "-z"], { encoding: "utf8", maxBuffer: 32 * 1024 * 1024 });
  assert.equal(result.status, 0, result.stderr);
  const trackedFiles = new Set([...result.stdout.split("\0").filter(Boolean), "contracts/ci-change-plan-policy.json", "scripts/ci-change-plan.mjs", "scripts/ci-change-plan.test.mjs", "scripts/ci-change-plan-coverage.test.mjs", "scripts/ci-required-contexts.test.mjs"]);
  const unexpected = [...trackedFiles].filter(path => {
    const plan = planCiChanges([{ status: "M", path }], policy);
    return plan.full && !intentionalFullVerification.some(pattern => pattern.test(path));
  });
  assert.deepEqual(unexpected, []);
});

import { appendFileSync, readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const scopeNames = ["frontend", "jvm", "verification", "deployment", "codeqlJava", "codeqlJavaScript", "dependencyReview", "documentation"];

function matchesSelector(selector = {}, path) {
  if ((selector.excludePaths ?? []).includes(path)) return false;
  return (selector.paths ?? []).includes(path)
    || (selector.pathPrefixes ?? []).some(prefix => path.startsWith(prefix))
    || (selector.extensions ?? []).some(extension => path.endsWith(extension))
    || (selector.patterns ?? []).some(pattern => new RegExp(pattern, "u").test(path));
}

export function validateCiChangePlanPolicy(policy) {
  const problems = [];
  if (policy?.schemaVersion !== 1) problems.push("ci change-plan policy schemaVersion must be 1");
  for (const name of scopeNames) if (!policy?.scopes?.[name]) problems.push(`ci change-plan policy must define ${name}`);
  for (const [name, selector] of Object.entries({ safeNoop: policy?.safeNoop, control: policy?.control, ...policy?.scopes })) {
    if (!selector || typeof selector !== "object") {
      problems.push(`ci change-plan policy ${name} must be an object`);
      continue;
    }
    for (const key of ["paths", "excludePaths", "pathPrefixes", "extensions", "patterns"]) {
      if (selector[key] !== undefined && (!Array.isArray(selector[key]) || !selector[key].every(value => typeof value === "string")))
        problems.push(`ci change-plan policy ${name}.${key} must be an array of strings`);
    }
    for (const pattern of selector.patterns ?? []) {
      try { new RegExp(pattern, "u"); } catch { problems.push(`ci change-plan policy ${name}.patterns contains an invalid regular expression`); }
    }
  }
  return problems;
}

export function planCiChanges(changes, policy) {
  const problems = validateCiChangePlanPolicy(policy);
  if (problems.length) throw new Error(problems.join("\n"));
  const paths = new Set();
  for (const change of changes) {
    if (!change || typeof change.path !== "string" || !change.path) throw new Error("ci change-plan received a change without a path");
    paths.add(change.path);
    if (change.previousPath !== undefined) {
      if (typeof change.previousPath !== "string" || !change.previousPath) throw new Error("ci change-plan received a rename without a previous path");
      paths.add(change.previousPath);
    }
  }
  const plan = Object.fromEntries(scopeNames.map(name => [name, false]));
  const unclassifiedPaths = [];
  let controlTouched = false;
  for (const path of [...paths].sort()) {
    if (matchesSelector(policy.control, path)) {
      for (const name of scopeNames) plan[name] = true;
      controlTouched = true;
      continue;
    }
    if (matchesSelector(policy.safeNoop, path)) continue;
    let matched = false;
    for (const name of scopeNames) {
      if (matchesSelector(policy.scopes[name], path)) { plan[name] = true; matched = true; }
    }
    if (!matched) unclassifiedPaths.push(path);
  }
  if (unclassifiedPaths.length) for (const name of scopeNames) plan[name] = true;
  return { ...plan, full: controlTouched || unclassifiedPaths.length > 0, changedPaths: [...paths].sort(), unclassifiedPaths };
}

export function parseGitNameStatus(buffer) {
  const fields = Buffer.from(buffer).toString("utf8").split("\0");
  fields.pop();
  const changes = [];
  for (let index = 0; index < fields.length;) {
    const status = fields[index++];
    if (!status) continue;
    if (/^[RC]/u.test(status)) {
      const previousPath = fields[index++]; const path = fields[index++];
      if (!previousPath || !path) throw new Error("Malformed rename/copy record from git diff");
      changes.push({ status: status[0], previousPath, path });
    } else {
      const path = fields[index++];
      if (!/^[ADMUTX]/u.test(status) || !path) throw new Error(`Malformed status record from git diff: ${status}`);
      changes.push({ status: status[0], path });
    }
  }
  return changes;
}

export function readExactChanges(base, head) {
  for (const revision of [base, head]) {
    const resolved = spawnSync("git", ["rev-parse", "--verify", `${revision}^{commit}`], { cwd: repositoryRoot, encoding: "utf8" });
    if (resolved.status !== 0) throw new Error(`Unable to resolve exact commit ${revision}`);
  }
  const result = spawnSync("git", ["diff", "--find-renames", "--name-status", "-z", base, head], { cwd: repositoryRoot, encoding: "buffer" });
  if (result.status !== 0) throw new Error(result.stderr.toString("utf8") || "Unable to compare exact commits");
  return parseGitNameStatus(result.stdout);
}

function allPlan() { return { ...Object.fromEntries(scopeNames.map(name => [name, true])), full: true, changedPaths: [], unclassifiedPaths: ["forced full verification"] }; }

function parseArguments(arguments_) {
  const options = { all: false, json: false, githubOutput: undefined, base: undefined, head: undefined };
  for (let index = 0; index < arguments_.length; index += 1) {
    const argument = arguments_[index];
    if (argument === "--all") options.all = true;
    else if (argument === "--json") options.json = true;
    else if (["--base", "--head", "--github-output"].includes(argument)) options[argument.slice(2).replace(/-([a-z])/gu, (_, letter) => letter.toUpperCase())] = arguments_[++index];
    else throw new Error(`Unknown argument ${argument}`);
  }
  if (!options.all && (!options.base || !options.head)) throw new Error("--base and --head are required unless --all is used");
  if (options.all && (options.base || options.head)) throw new Error("--all cannot be combined with --base or --head");
  return options;
}

export function writeGithubOutput(plan, outputPath) {
  const outputNames = { frontend: "frontend", jvm: "jvm", verification: "verification", deployment: "deployment", codeqlJava: "codeql-java", codeqlJavaScript: "codeql-javascript", dependencyReview: "dependency-review", documentation: "documentation" };
  const lines = scopeNames.map(name => `${outputNames[name]}=${plan[name]}`);
  lines.push(`full=${plan.full}`, `reason=${plan.full ? "unclassified or CI-control paths require every lane" : "only relevant verification lanes are enabled"}`);
  appendFileSync(outputPath, `${lines.join("\n")}\n`);
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const options = parseArguments(process.argv.slice(2));
    const policy = JSON.parse(readFileSync(join(repositoryRoot, "contracts/ci-change-plan-policy.json"), "utf8"));
    const plan = options.all ? allPlan() : planCiChanges(readExactChanges(options.base, options.head), policy);
    if (options.githubOutput) writeGithubOutput(plan, options.githubOutput);
    if (options.json || !options.githubOutput) process.stdout.write(`${JSON.stringify(plan)}\n`);
  } catch (error) { console.error(error instanceof Error ? error.message : String(error)); process.exitCode = 2; }
}

import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";

import { parseGitNameStatus, planCiChanges, readExactChanges, validateCiChangePlanPolicy, writeGithubOutput } from "./ci-change-plan.mjs";

const policy = JSON.parse(readFileSync(new URL("../contracts/ci-change-plan-policy.json", import.meta.url), "utf8"));
const changed = (...paths) => paths.map(path => ({ status: "M", path }));

test("ci change-plan policy is complete", () => assert.deepEqual(validateCiChangePlanPolicy(policy), []));
test("rejects malformed policies and missing exact revisions", () => {
  assert.ok(validateCiChangePlanPolicy({ schemaVersion: 0, scopes: {} }).length > 0);
  assert.throws(() => planCiChanges(changed("README.md"), { schemaVersion: 1, scopes: {} }), /must define/u);
  assert.throws(() => readExactChanges("not-a-commit", "HEAD"), /Unable to resolve exact commit/u);
});
test("parses NUL-delimited deletion and rename records", () => {
  assert.deepEqual(parseGitNameStatus(Buffer.from("D\0docs/old.md\0R100\0README.md\0docs/new.md\0")), [{ status: "D", path: "docs/old.md" }, { status: "R", previousPath: "README.md", path: "docs/new.md" }]);
});
test("routes README and docs changes through the cheap documentation lane", () => {
  for (const path of ["README.md", "docs/getting-started.md", "frontend/docs/architecture/README.md"]) {
    const plan = planCiChanges(changed(path), policy);
    assert.equal(plan.documentation, true, path);
    for (const lane of ["frontend", "jvm", "verification", "deployment", "codeqlJava", "codeqlJavaScript", "dependencyReview"]) assert.equal(plan[lane], false, `${path}:${lane}`);
    assert.equal(plan.full, false, path);
  }
});
test("routes frontend, JVM, and deployment inputs to their owning lanes", () => {
  const frontend = planCiChanges(changed("frontend/src/app/App.tsx"), policy);
  assert.equal(frontend.frontend, true); assert.equal(frontend.verification, true); assert.equal(frontend.deployment, true); assert.equal(frontend.codeqlJavaScript, true); assert.equal(frontend.jvm, false);
  const jvm = planCiChanges(changed("src/main/java/com/vireocode/startertemplate/MainApplication.java"), policy);
  assert.equal(jvm.jvm, true); assert.equal(jvm.verification, true); assert.equal(jvm.deployment, true); assert.equal(jvm.codeqlJava, true); assert.equal(jvm.frontend, false);
  const descriptor = planCiChanges(changed("compose.yaml"), policy);
  assert.equal(descriptor.deployment, true); assert.equal(descriptor.dependencyReview, true);
  for (const path of [".dockerignore", "frontend/.dockerignore"]) {
    assert.equal(planCiChanges(changed(path), policy).deployment, true, path);
  }
  const frontendTest = planCiChanges(changed("frontend/tests/unit/app-pages.test.ts"), policy);
  assert.equal(frontendTest.verification, true); assert.equal(frontendTest.deployment, false);
  const jvmTest = planCiChanges(changed("src/test/java/example/AppTest.java"), policy);
  assert.equal(jvmTest.verification, true); assert.equal(jvmTest.deployment, false);
});
test("routes manifests to dependency review and CI controls fail closed", () => {
  const dependency = planCiChanges(changed("frontend/package-lock.json"), policy);
  assert.equal(dependency.dependencyReview, true); assert.equal(dependency.full, false);
  const control = planCiChanges(changed(".github/workflows/ci.yml"), policy);
  for (const [lane, selected] of Object.entries(control).filter(([name]) => !["full", "changedPaths", "unclassifiedPaths"].includes(name))) assert.equal(selected, true, lane);
  assert.equal(control.full, true);
});
test("unknown, deleted, and renamed paths fail closed", () => {
  assert.equal(planCiChanges(changed("new/unclassified.file"), policy).full, true);
  assert.equal(planCiChanges([{ status: "D", path: "new/deleted.file" }], policy).full, true);
  assert.equal(planCiChanges([{ status: "R", previousPath: "new/old.file", path: "docs/new.md" }], policy).full, true);
});
test("writes stable GitHub output", () => {
  const directory = mkdtempSync(join(tmpdir(), "vireo-template-ci-plan-")); const output = join(directory, "output");
  try {
    writeGithubOutput(planCiChanges(changed("README.md"), policy), output);
    const result = readFileSync(output, "utf8");
    assert.match(result, /^documentation=true$/mu); assert.match(result, /^verification=false$/mu); assert.match(result, /^reason=only relevant verification lanes are enabled$/mu);
  } finally { rmSync(directory, { recursive: true, force: true }); }
});

import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import test from "node:test";

const read = path => readFileSync(new URL(`../${path}`, import.meta.url), "utf8");
const rulesetUrl = new URL("../.github/rulesets/main.json", import.meta.url);
const ruleset = existsSync(rulesetUrl) ? JSON.parse(readFileSync(rulesetUrl, "utf8")) : undefined;
const actionContexts = ruleset?.rules.find(rule => rule.type === "required_status_checks").parameters.required_status_checks.filter(check => check.integration_id === 15368).map(check => check.context).sort();

function jobBlock(workflow, job) {
  const lines = workflow.split("\n");
  const start = lines.indexOf(`  ${job}:`);
  const end = lines.findIndex((line, index) => index > start && /^ {2}[A-Za-z0-9_-]+:$/u.test(line));
  return start < 0 ? "" : lines.slice(start, end < 0 ? undefined : end).join("\n");
}

test("required contexts remain exact and always report on pull requests", { skip: !ruleset }, () => {
  assert.deepEqual(actionContexts, ["Application and deployment verification", "CodeQL analysis", "Dependency review", "Secret history scan"]);
  for (const [path, job, context, expectedIf] of [[".github/workflows/ci.yml", "verify", "Application and deployment verification", "always()"], [".github/workflows/codeql.yml", "analyze", "CodeQL analysis", "always()"], [".github/workflows/security.yml", "dependency-review", "Dependency review", "always() && github.event_name == 'pull_request'"], [".github/workflows/security.yml", "secret-scan", "Secret history scan", null]]) {
    const workflow = read(path); const block = jobBlock(workflow, job);
    assert.match(workflow, /^ {2}pull_request:/mu, `${context} must be available to pull requests`);
    assert.notEqual(block, "", `${context} must exist`);
    assert.match(block, new RegExp(`^    name: ${context.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}$`, "mu"));
    const ifLine = block.split("\n").find(line => line.startsWith("    if:"));
    assert.equal(ifLine ?? null, expectedIf === null ? null : `    if: ${expectedIf}`);
  }
});

test("the independent GitHub CodeQL integration and consolidated security workflow remain required", { skip: !ruleset }, () => {
  const checks = ruleset.rules.find(rule => rule.type === "required_status_checks").parameters.required_status_checks;
  assert.ok(checks.some(check => check.context === "CodeQL" && check.integration_id === 57789));
  assert.equal(
    existsSync(new URL("../.github/workflows/dependency-review.yml", import.meta.url)),
    false,
  );
});

test("selected dependency review checks out the pull request before analysis", () => {
  const security = read(".github/workflows/security.yml");
  const review = jobBlock(security, "dependency-review");
  const checkout = review.indexOf("uses: actions/checkout@");
  const analysis = review.indexOf("uses: actions/dependency-review-action@");
  assert.ok(checkout >= 0 && checkout < analysis);
  assert.match(review, /persist-credentials: false/u);
});

test("required verification propagates documentation and routing failures", () => {
  const workflow = read(".github/workflows/ci.yml");
  const verification = jobBlock(workflow, "verify");
  assert.match(verification, /COORDINATOR_RESULT: \$\{\{ needs\.changes\.result \}\}/u);
  assert.match(verification, /test "\$COORDINATOR_RESULT" = success/u);
});

test("documentation validation remains safe in projected applications", () => {
  const workflow = read(".github/workflows/ci.yml");
  assert.match(workflow, /git diff --check "\$BASE_SHA" "\$HEAD_SHA"/u);
  assert.match(workflow, /if \[ -f scripts\/public-contract-policy\.mjs \]; then/u);
});

test("pull-request planners execute the trusted base revision or fail closed", () => {
  for (const path of [
    ".github/workflows/ci.yml",
    ".github/workflows/codeql.yml",
    ".github/workflows/security.yml",
  ]) {
    const workflow = read(path);
    assert.match(workflow, /git cat-file -e "\$BASE_SHA:scripts\/ci-change-plan\.mjs"/u, path);
    assert.match(workflow, /git worktree add --detach "\$planner_root" "\$BASE_SHA"/u, path);
    assert.match(workflow, /node "\$planner_root\/scripts\/ci-change-plan\.mjs"/u, path);
    assert.match(workflow, /^\s*verification=true$/mu, path);
    assert.match(workflow, /^\s*deployment=true$/mu, path);
    assert.match(workflow, /^\s*codeql-java=true$/mu, path);
    assert.match(workflow, /^\s*codeql-javascript=true$/mu, path);
    assert.match(workflow, /^\s*dependency-review=true$/mu, path);
    assert.match(workflow, /reason=base-planner-unavailable; running every lane/u, path);
  }
});

test("documentation-only pull requests retain GitHub's independent CodeQL result", () => {
  const workflow = read(".github/workflows/codeql.yml");
  const javascript = jobBlock(workflow, "analyze-javascript");
  assert.match(
    javascript,
    /github\.event_name == 'pull_request' \|\| needs\.changes\.outputs\.javascript == 'true'/u,
  );
});

