  for (const expectedIcon of PWA_POLICY.icons) {
    if (
      !manifest.icons.some(
        icon =>
          icon?.src === expectedIcon.src &&
          icon?.sizes === expectedIcon.sizes &&
          icon?.type === expectedIcon.type &&
          icon?.purpose === expectedIcon.purpose,
      )
    ) {
